// Fetch all active deals from CRM
// In production, this would call CRM API

// Example deal structure
const deals = [
  /*
  {
    id: 'deal_001',
    name: 'Acme Corp - Enterprise License',
    company: 'Acme Corporation',
    contactName: 'John Smith',
    contactEmail: 'john@acme.com',
    amount: 150000,
    currency: 'USD',
    stage: 'Negotiation',
    stageOrder: 4,
    probability: 60,
    expectedCloseDate: '2026-01-15',
    createdAt: '2025-11-01',
    lastActivityDate: '2026-01-02',
    lastActivityType: 'Email',
    owner: 'Sarah Johnson',
    ownerEmail: 'sarah@company.com',
    daysInStage: 14,
    daysOpen: 67,
    nextStep: 'Send final proposal',
    lossReason: null,
    competitors: ['Competitor A', 'Competitor B'],
    notes: 'Large enterprise deal, multi-year contract'
  }
  */
];

// Add calculated fields
const today = new Date();
const enrichedDeals = deals.map(deal => {
  const closeDate = new Date(deal.expectedCloseDate);
  const lastActivity = new Date(deal.lastActivityDate);
  const daysToClose = Math.ceil((closeDate - today) / (1000 * 60 * 60 * 24));
  const daysSinceActivity = Math.ceil((today - lastActivity) / (1000 * 60 * 60 * 24));

  return {
    ...deal,
    daysToClose,
    daysSinceActivity,
    isStale: daysSinceActivity > 7,
    isClosingSoon: daysToClose <= 7 && daysToClose > 0,
    isOverdue: daysToClose < 0,
    isAtRisk: deal.probability < 40 || daysSinceActivity > 14
  };
});

return { json: { deals: enrichedDeals, fetchedAt: today.toISOString() } };

// Analyze pipeline and categorize deals
const data = $input.first().json;
const deals = data.deals || [];

// Define stage order for pipeline
const stageOrder = {
  'Qualification': 1,
  'Discovery': 2,
  'Proposal': 3,
  'Negotiation': 4,
  'Closed Won': 5,
  'Closed Lost': 6
};

// Categorize deals
const staleDeals = deals.filter(d => d.isStale && !['Closed Won', 'Closed Lost'].includes(d.stage));
const closingSoon = deals.filter(d => d.isClosingSoon && !['Closed Won', 'Closed Lost'].includes(d.stage));
const atRiskDeals = deals.filter(d => d.isAtRisk && !['Closed Won', 'Closed Lost'].includes(d.stage));
const overdueDeals = deals.filter(d => d.isOverdue && !['Closed Won', 'Closed Lost'].includes(d.stage));

// Active pipeline (exclude closed)
const activePipeline = deals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage));

// Pipeline by stage
const byStage = {};
activePipeline.forEach(deal => {
  if (!byStage[deal.stage]) {
    byStage[deal.stage] = { count: 0, value: 0, deals: [] };
  }
  byStage[deal.stage].count++;
  byStage[deal.stage].value += deal.amount;
  byStage[deal.stage].deals.push(deal);
});

// Pipeline by owner
const byOwner = {};
activePipeline.forEach(deal => {
  if (!byOwner[deal.owner]) {
    byOwner[deal.owner] = { count: 0, value: 0, deals: [] };
  }
  byOwner[deal.owner].count++;
  byOwner[deal.owner].value += deal.amount;
  byOwner[deal.owner].deals.push(deal);
});

const analysis = {
  timestamp: new Date().toISOString(),
  totalDeals: activePipeline.length,
  totalValue: activePipeline.reduce((sum, d) => sum + d.amount, 0),
  weightedValue: activePipeline.reduce((sum, d) => sum + (d.amount * d.probability / 100), 0),

  staleDeals,
  staleCount: staleDeals.length,
  staleValue: staleDeals.reduce((sum, d) => sum + d.amount, 0),

  closingSoon,
  closingSoonCount: closingSoon.length,
  closingSoonValue: closingSoon.reduce((sum, d) => sum + d.amount, 0),

  atRiskDeals,
  atRiskCount: atRiskDeals.length,
  atRiskValue: atRiskDeals.reduce((sum, d) => sum + d.amount, 0),

  overdueDeals,
  overdueCount: overdueDeals.length,
  overdueValue: overdueDeals.reduce((sum, d) => sum + d.amount, 0),

  byStage,
  byOwner
};

return { json: analysis };

// Check for stale deals (no activity in 7+ days)
const data = $input.first().json;
const staleDeals = data.staleDeals || [];

if (staleDeals.length === 0) {
  return { json: { hasStaleDeals: false, message: 'No stale deals found' } };
}

// Group by owner
const byOwner = {};
staleDeals.forEach(deal => {
  if (!byOwner[deal.owner]) {
    byOwner[deal.owner] = [];
  }
  byOwner[deal.owner].push(deal);
});

return {
  json: {
    hasStaleDeals: true,
    count: staleDeals.length,
    totalValue: data.staleValue,
    byOwner,
    deals: staleDeals
  }
};

// Check for deals closing soon (within 7 days)
const data = $input.first().json;
const closingSoon = data.closingSoon || [];

if (closingSoon.length === 0) {
  return { json: { hasClosingSoon: false, message: 'No deals closing soon' } };
}

// Group by owner
const byOwner = {};
closingSoon.forEach(deal => {
  if (!byOwner[deal.owner]) {
    byOwner[deal.owner] = [];
  }
  byOwner[deal.owner].push(deal);
});

return {
  json: {
    hasClosingSoon: true,
    count: closingSoon.length,
    totalValue: data.closingSoonValue,
    byOwner,
    deals: closingSoon
  }
};

// Check for at-risk deals
const data = $input.first().json;
const atRiskDeals = data.atRiskDeals || [];

if (atRiskDeals.length === 0) {
  return { json: { hasAtRisk: false, message: 'No at-risk deals found' } };
}

// Group by owner
const byOwner = {};
atRiskDeals.forEach(deal => {
  if (!byOwner[deal.owner]) {
    byOwner[deal.owner] = [];
  }
  byOwner[deal.owner].push(deal);
});

return {
  json: {
    hasAtRisk: true,
    count: atRiskDeals.length,
    totalValue: data.atRiskValue,
    byOwner,
    deals: atRiskDeals
  }
};

// Calculate pipeline metrics
const data = $input.first().json;

const formatCurrency = (amount) => {
  return '$' + amount.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

const metrics = {
  timestamp: data.timestamp,

  // Overall metrics
  totalPipeline: formatCurrency(data.totalValue),
  totalPipelineRaw: data.totalValue,
  weightedPipeline: formatCurrency(data.weightedValue),
  weightedPipelineRaw: data.weightedValue,
  dealCount: data.totalDeals,
  averageDealSize: data.totalDeals > 0 ? formatCurrency(data.totalValue / data.totalDeals) : '$0',

  // Health indicators
  staleDeals: data.staleCount,
  staleValue: formatCurrency(data.staleValue),
  atRiskDeals: data.atRiskCount,
  atRiskValue: formatCurrency(data.atRiskValue),
  overdueDeals: data.overdueCount,
  overdueValue: formatCurrency(data.overdueValue),
  closingSoon: data.closingSoonCount,
  closingSoonValue: formatCurrency(data.closingSoonValue),

  // By stage
  byStage: Object.entries(data.byStage).map(([stage, info]) => ({
    stage,
    count: info.count,
    value: formatCurrency(info.value)
  })),

  // By owner
  byOwner: Object.entries(data.byOwner).map(([owner, info]) => ({
    owner,
    count: info.count,
    value: formatCurrency(info.value)
  })),

  // Health score (0-100)
  healthScore: Math.max(0, 100 - (data.staleCount * 5) - (data.atRiskCount * 10) - (data.overdueCount * 15))
};

return { json: metrics };

