// Handle stage change
const deal = $input.first().json;

const stageEmojis = {
  'Qualification': ':mag:',
  'Discovery': ':bulb:',
  'Proposal': ':page_facing_up:',
  'Negotiation': ':handshake:'
};

const formatCurrency = (amount) => {
  return '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

return {
  json: {
    ...deal,
    emoji: stageEmojis[deal.stage] || ':arrow_right:',
    formattedAmount: formatCurrency(deal.amount),
    notification: `Deal moved from ${deal.previousStage} to ${deal.stage}`
  }
};

// Handle deal won
const deal = $input.first().json;

const formatCurrency = (amount) => {
  return '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

return {
  json: {
    ...deal,
    formattedAmount: formatCurrency(deal.amount),
    celebration: true,
    notification: `🎉 DEAL WON: ${deal.dealName} - ${formatCurrency(deal.amount)}`
  }
};

// Handle deal lost
const deal = $input.first().json;

const formatCurrency = (amount) => {
  return '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

return {
  json: {
    ...deal,
    formattedAmount: formatCurrency(deal.amount),
    notification: `Deal Lost: ${deal.dealName} - ${formatCurrency(deal.amount)}`,
    analysis: {
      lossReason: deal.lossReason || 'Not specified',
      competitor: deal.competitor || 'Not specified',
      stageAtLoss: deal.previousStage,
      notes: deal.notes
    }
  }
};

// Handle amount change
const deal = $input.first().json;

const formatCurrency = (amount) => {
  return '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

const change = deal.amount - (deal.previousAmount || 0);
const changePercent = deal.previousAmount ? ((change / deal.previousAmount) * 100).toFixed(1) : 0;

return {
  json: {
    ...deal,
    formattedAmount: formatCurrency(deal.amount),
    formattedPreviousAmount: formatCurrency(deal.previousAmount),
    formattedChange: formatCurrency(Math.abs(change)),
    changePercent,
    isIncrease: change > 0,
    notification: `Deal amount ${change > 0 ? 'increased' : 'decreased'} by ${formatCurrency(Math.abs(change))} (${changePercent}%)`
  }
};

// Handle close date change
const deal = $input.first().json;

const formatCurrency = (amount) => {
  return '$' + (amount || 0).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
};

const newDate = new Date(deal.expectedCloseDate);
const oldDate = new Date(deal.previousCloseDate);
const daysDiff = Math.ceil((newDate - oldDate) / (1000 * 60 * 60 * 24));

return {
  json: {
    ...deal,
    formattedAmount: formatCurrency(deal.amount),
    formattedNewDate: newDate.toLocaleDateString(),
    formattedOldDate: oldDate.toLocaleDateString(),
    daysDiff,
    isPushed: daysDiff > 0,
    notification: `Close date ${daysDiff > 0 ? 'pushed' : 'pulled in'} by ${Math.abs(daysDiff)} days`
  }
};

